# Hopcroft-Karp for bipartite matching ---------------------------------------

def hopcroft_karp(adj, left_size, right_size):
    INF = 10 ** 9
    pair_left = [-1] * left_size
    pair_right = [-1] * right_size
    dist = [0] * left_size

    def bfs():
        q = deque()
        for u in range(left_size):
            if pair_left[u] == -1:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = INF
        reachable_free = False
        while q:
            u = q.popleft()
            for v in adj[u]:
                if pair_right[v] == -1:
                    reachable_free = True
                elif dist[pair_right[v]] == INF:
                    dist[pair_right[v]] = dist[u] + 1
                    q.append(pair_right[v])
        return reachable_free

    def dfs(u):
        for v in adj[u]:
            if pair_right[v] == -1 or (dist[pair_right[v]] == dist[u] + 1 and dfs(pair_right[v])):
                pair_left[u] = v
                pair_right[v] = u
                return True
        dist[u] = INF
        return False

    matching = 0
    while bfs():
        for u in range(left_size):
            if pair_left[u] == -1 and dfs(u):
                matching += 1
    return matching

# -----------------------------------------------------------------------------

def main():
    n, m, grid = read_input()

    # Label horizontal runs (consecutive '#' in each row)
    h_id = [[-1] * m for _ in range(n)]
    h_count = 0
    for i in range(n):
        j = 0
        while j < m:
            if grid[i][j] == '#':
                k = j
                while k < m and grid[i][k] == '#':
                    h_id[i][k] = h_count
                    k += 1
                h_count += 1
                j = k
            else:
                j += 1

    # Label vertical runs (consecutive '#' in each column)
    v_id = [[-1] * m for _ in range(n)]
    v_count = 0
    for j in range(m):
        i = 0
        while i < n:
            if grid[i][j] == '#':
                k = i
                while k < n and grid[k][j] == '#':
                    v_id[k][j] = v_count
                    k += 1
                v_count += 1
                i = k
            else:
                i += 1

    # Build bipartite graph: horizontal run (left) -> vertical run (right)
    adj = [[] for _ in range(h_count)]
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                u = h_id[i][j]
                v = v_id[i][j]
                adj[u].append(v)

    # Maximum matching equals minimum vertex cover in bipartite graphs
    max_match = hopcroft_karp(adj, h_count, v_count)
    print(max_match)

