def roman_number_operations(first_number, operation=None, second_number=None, conversion_type='int_to_roman'):
    numerals = {1: "i", 4: "iv", 5: "v", 9: "ix",
                10: "x", 40: "xl", 50: "l", 90: "xc",
                100: "c", 400: "cd", 500: "d", 900: "cm", 1000: "m"}
    values = {v: k for k, v in numerals.items()}

    def int_to_roman(num):
        result = ""
        for value, numeral in sorted(numerals.items(), reverse=True):
            while num >= value:
                result += numeral
                num -= value
        return result

    def roman_to_int(roman):
        result = 0
        i = 0
        while i < len(roman):
            if i + 1 < len(roman) and roman[i:i+2] in values:
                result += values[roman[i:i+2]]
                i += 2
            else:
                result += values[roman[i]]
                i += 1
        return result

    if isinstance(first_number, str):
        first_number = roman_to_int(first_number.lower())
    if isinstance(second_number, str):
        second_number = roman_to_int(second_number.lower())

    if operation:
        try:
            if operation == '+':
                result = first_number + second_number
            elif operation == '-':
                result = first_number - second_number
            elif operation == '*':
                result = first_number * second_number
            elif operation == '/':
                result = first_number / second_number
            else:
                raise ValueError('Invalid Operation')
        except ZeroDivisionError:
            raise ValueError('Cannot divide by zero')
    else:
        result = first_number

    if conversion_type == 'int_to_roman':
        return int_to_roman(result).lower()
    elif conversion_type == 'roman_to_int':
        return result
    else:
        raise ValueError('Invalid Conversion Type')

