    {"m", 1000}, {"cm", 900}, {"d", 500}, {"cd", 400}, 
    {"c", 100}, {"xc", 90}, {"l", 50}, {"xl", 40}, 
    {"x", 10}, {"ix", 9}, {"v", 5}, {"iv", 4}, {"i", 1}};

std::string int_to_roman(int num) {
    std::string result;
    for (auto& pair : numerals) {
        while (num >= pair.first) {
            result += pair.second;
            num -= pair.first;
        }
    }
    return result;
}

int roman_to_int(std::string roman) {
    int result = 0, i = 0;
    while (i < roman.size()) {
        if (i + 1 < roman.size() && 
            values.find(roman.substr(i, 2)) != values.end()) {
            result += values[roman.substr(i, 2)];
            i += 2;
        } else {
            result += values[std::string(1, roman[i])];
            i += 1;
        }
    }
    return result;
}

