import Foundation

func customMixStrings(s1: String, s2: String) -> String {

    //Use Swift's min function to find the smallest length between the two strings
    let minLen = min(s1.count, s2.count)

    //This array will store the mixed characters from the two strings
    var result = [Character]()

    //Swift strings are not directly indexable like Python so we'll create an array of their characters
    let s1Chars = Array(s1)
    let s2Chars = Array(s2)

    //Instead of slicing and stepping like in Python, we'll use a for-loop to mix characters
    for i in 0..<minLen {
        result.append(s1Chars[i])
        result.append(s2Chars[i])
    }

    //If s1 is longer than s2, append the remaining characters from s1
    if s1.count > minLen {
        result.append(contentsOf: s1Chars[minLen..<s1.count])
    }

    //If s2 is longer than s1, append the remaining characters from s2
    else if s2.count > minLen {
        result.append(contentsOf: s2Chars[minLen..<s2.count])
    }

    //Reverse the array and join it into a single string
    let output = String(result.reversed())
    return output
}
