import re
import operator

OPERATORS = {
    '+': (1, operator.add),
    '-': (1, operator.sub),
    '*': (2, operator.mul),
    '/': (2, operator.truediv),
    '**': (3, operator.pow),
}

UNARY_OPERATORS = {
    '-': (4, operator.neg),
}

def parse_expression(expression):
    token_specification = [
        ('NUMBER',   r'\d+(\.\d*)?'),
        ('POW',      r'\*\*'),
        ('OP',       r'[+\-*/]'),
        ('LPAREN',   r'\('),
        ('RPAREN',   r'\)'),
        ('SKIP',     r'[ \t]+'),
        ('MISMATCH', r'.'),
    ]
    tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)
    for mo in re.finditer(tok_regex, expression):
        kind = mo.lastgroup
        value = mo.group()
        if kind == 'NUMBER':
            value = float(value) if '.' in value else int(value)
        elif kind == 'POW':
            kind = 'OP'
        elif kind == 'SKIP':
            continue
        elif kind == 'MISMATCH':
            raise RuntimeError(f'Unexpected character {value!r}')
        yield kind, value

def evaluate_expression(expression):
    def precedence(op):
        if isinstance(op, Operator):
            if op.is_unary:
                return UNARY_OPERATORS[op.operator][0]
            else:
                return OPERATORS[op.operator][0]
        return 0
    def is_right_associative(op):
        if isinstance(op, Operator):
            return op.operator == '**' or op.is_unary
        return False
    def apply_operator(op, stack):
        if op.is_unary:
            right = stack.pop()
            result = UNARY_OPERATORS[op.operator][1](right)
        else:
            right = stack.pop()
            left = stack.pop()
            result = OPERATORS[op.operator][1](left, right)
        stack.append(result)
    class Operator:
        def __init__(self, operator, is_unary=False):
            self.operator = operator
            self.is_unary = is_unary
    stack = []
    ops = []
    tokens = list(parse_expression(expression))
    i = 0
    unary_expected = True
    while i < len(tokens):
        token_type, token_value = tokens[i]
        if token_type == 'NUMBER':
            stack.append(token_value)
            unary_expected = False
        elif token_type == 'OP':
            op_str = token_value
            if op_str == '*' and i+1 < len(tokens) and tokens[i+1][0] == 'OP' and tokens[i+1][1] == '*':
                op_str = '**'
                i += 1
            if unary_expected and op_str == '-':
                curr_op = Operator('-', is_unary=True)
            else:
                curr_op = Operator(op_str, is_unary=False)
            while (ops and ops[-1].operator != '(' and
                   ((precedence(ops[-1]) > precedence(curr_op)) or
                    (precedence(ops[-1]) == precedence(curr_op) and not is_right_associative(curr_op)))):
                apply_operator(ops.pop(), stack)
            ops.append(curr_op)
            unary_expected = True
        elif token_type == 'LPAREN':
            ops.append(Operator('('))
            unary_expected = True
        elif token_type == 'RPAREN':
            while ops and ops[-1].operator != '(':           
                apply_operator(ops.pop(), stack)
            if not ops or ops[-1].operator != '(':  
                raise RuntimeError('Mismatched parentheses')
            ops.pop()  # remove '('
            unary_expected = False
        i += 1
    while ops:
        if ops[-1].operator == '(':        
            raise RuntimeError('Mismatched parentheses')
        apply_operator(ops.pop(), stack)
    return stack[0]

def main():
    expr = input()
    res = evaluate_expression(expr)
    print(res)

if __name__ == "__main__":
    main()

from datetime import datetime

class Book:
    all_books = []

    def __init__(self, title, author, isbn, publication_date):
        self.title = title
        self.author = author
        self.isbn = isbn
        self.publication_date = publication_date
        Book.all_books.append(self)

    def display_details(self):
        print(f"Title: {self.title}, Author: {self.author}, ISBN: {self.isbn}, Publication Date: {self.publication_date}")

    @staticmethod
    def get_sorted_books():
        current_year = datetime.now().year
        ten_years_ago = current_year - 10

        valid_books = []
        seen_isbns = set()
        for book in Book.all_books:
            try:
                pub_date = datetime.strptime(book.publication_date, "%Y-%m-%d")
                if pub_date.year >= ten_years_ago:
                    if book.isbn not in seen_isbns:
                        valid_books.append(book)
                        seen_isbns.add(book.isbn)
            except ValueError:
                continue
        valid_books.sort(key=lambda x: x.isbn)
        return valid_books

def main():
    N = int(input())
    for _ in range(N):
        title = input().strip()
        author = input().strip()
        isbn = input().strip()
        publication_date = input().strip()
        Book(title, author, isbn, publication_date)
    sorted_books = Book.get_sorted_books()
    for book in sorted_books:
        book.display_details()

