def is_alpha_num(c):
    return ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9')

def to_lower(c):
    if 'A' <= c <= 'Z':
        return chr(ord(c) + (ord('a') - ord('A')))
    return c

def main():
    s = input()

    # Filter and lowercase
    filtered_chars = []
    for c in s:
        if is_alpha_num(c):
            filtered_chars.append(to_lower(c))

    # Convert to ASCII
    ascii_values = []
    for c in filtered_chars:
        ascii_values.append(ord(c))

    # Reverse ASCII manually
    reversed_ascii = []
    for i in range(len(ascii_values) - 1, -1, -1):
        reversed_ascii.append(ascii_values[i])

    # Convert back to chars
    reversed_chars = []
    for val in reversed_ascii:
        reversed_chars.append(chr(val))

    # Join into strings
    original_s = ''
    for c in filtered_chars:
        original_s += c
    reversed_s = ''
    for c in reversed_chars:
        reversed_s += c

    # Check palindrome
    if original_s == reversed_s:
        print('True')
    else:
        print('False')

if __name__ == "__main__":
    main()
